      SUBROUTINE PARAMC---- DEFINE A PARAMETERC-------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'KNAME.CIN'      INCLUDE 'LBDAT.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARLOC.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDWRDS.CIN'C-------------------------------------------------------------------      CHARACTER*8     LOCATE, PLACE      LOGICAL         FLAG      DATA LOCATE     /'LOCATION'/, PLACE /'PLACE'/C-------------------------------------------------------------------C      IPTYP(1) = 0      PDATA(1) = 0.0      LDATA = BLANK      NWRDS = 0CC---- COMMA?C      CALL RDNEXT      IF (ENDFIL) GO TO 900      IF (ITEM .EQ. COMMA) THEN        CALL RDNEXT        IF (ENDFIL) GO TO 900      ENDIF      IF (ITEM .EQ. EQUAL) GO TO 120CC---- PARAMETER NAMEC      CALL RDWORD(KNAME,LNAME)      IF (LNAME .EQ. 0) THEN        CALL RDFAIL        WRITE (IECHO,910)        GO TO 900      ENDIF      LBDAT = KNAME      CALL RDNEXT      IF (ENDFIL) GO TO 900CC---- EQUALS SIGN?C  120 IF (ITEM .EQ. EQUAL) THENCC---- KEEP VALUES TO TEST FOR REDEFINITIONC        IPT = -1CC---- PARAMETER EXPRESSIONC        IPARM = 1        CALL DECEXP        IF (ENDFIL) GO TO 900        FLAG = ERROR        NWRDS = 1        IF (FLAG) GO TO 800      ELSE        CALL RDBACK        IPTYP(IPARM) = -2      ENDIFCC---- LOCATION SPECIFICATION ? (FOR STORE COMMAND ONLY)C      CALL RDNEXT      IF (ENDFIL) GO TO 900      IF (ITEM .NE. COMMA) GO TO 300      CALL RDNEXT      IF (ENDFIL) GO TO 900      IF (INDEX(ALPHA,ITEM) .NE. 0) THEN        CALL RDWORD(KNAME,LNAME)        IF (LNAME .EQ. 0) THEN          CALL RDFAIL          WRITE (NOUT,910)          GO TO 800        ENDIF        IF (KNAME .NE. LOCATE(1:LNAME) .AND. KNAME .NE. PLACE(1:LNAME))     1      THEN          CALL RDFAIL          WRITE (NOUT,920) KNAME(1:LNAME)          GO TO 800        ENDIF        CALL RDNEXT        IF (ENDFIL) GO TO 900        IF (ITEM .EQ. EQUAL) THEN          CALL RDNEXT          IF (ENDFIL) GO TO 900          CALL RDWORD(LDATA,LLOC)          IF (LLOC .EQ. 0) THEN            CALL RDFAIL            WRITE (NOUT,910)            GO TO 800          ENDIF        ENDIF        CALL RDNEXT        IF (ENDFIL) GO TO 900      ELSE        CALL RDFIND(';')        IF (ENDFIL) GO TO 900        ERROR = .TRUE.        GO TO 800      ENDIFCC---- END OF COMMAND?C  300 CALL RDTEST(';',FLAG)      IF (FLAG) GO TO 800CC---- TEST FOR REDEFINITIONC      IF (IPT .GE. 0) THEN        CALL RDWARN        WRITE (IECHO,950) IPT      ENDIF      NWORD = NWRDS + 1      GO TO 901CC---- ERROR EXIT --- LEAVE PARAMETER UNDEFINEDC  800 IPTYP(1) = -1      PDATA(1) = 0.0C  900 ERROR = .TRUE.  901 RETURNC-------------------------------------------------------------------  910 FORMAT(' *** ERROR *** PARAMETER NAME EXPECTED'/' ')  920 FORMAT(' *** ERROR *** UNKNOWN BEAM ELEMENT "',A,'"'/' ')  930 FORMAT(' *** ERROR *** PARAMETER KEYWORD EXPECTED'/' ')  940 FORMAT(' *** ERROR *** UNKNOWN ELEMENT PARAMETER "',     +       A,' ',A,' "'/' ')  950 FORMAT(' ** WARNING ** THE ABOVE NAME WAS DEFINED IN LINE ',I5,     +       ', IT WILL BE REDEFINED'/' ')C-------------------------------------------------------------------      END